187→        ui.set_prompt_response("recovery_bundler", "skip");
188→
189→        let action = prompt_recovery(&mut ui, "bundler", None, false).unwrap();
190→        assert_eq!(action, RecoveryAction::Skip);
191→    }
192→
193→    #[test]
194→    fn prompt_recovery_abort() {
195→        let mut ui = MockUI::new();
196→        ui.set_interactive(true);
197→        ui.set_prompt_response("recovery_test", "abort");
198→
199→        let action = prompt_recovery(&mut ui, "test", None, false).unwrap();
200→        assert_eq!(action, RecoveryAction::Abort);
201→    }
202→
203→    #[test]
204→    fn prompt_recovery_shell() {
205→        let mut ui = MockUI::new();
206→        ui.set_interactive(true);
207→        ui.set_prompt_response("recovery_test", "shell");
208→
209→        let action = prompt_recovery(&mut ui, "test", None, false).unwrap();
210→        assert_eq!(action, RecoveryAction::Shell);
211→    }
212→
213→    #[test]
214→    fn prompt_recovery_custom_fix_when_hint_present() {
215→        let mut ui = MockUI::new();
216→        ui.set_interactive(true);
217→        ui.queue_prompt_responses("recovery_test", vec!["custom_fix"]);
218→        ui.set_prompt_response("custom_fix_test", "chmod +x script.sh");
219→
220→        let action = prompt_recovery(&mut ui, "test", None, true).unwrap();
221→        assert_eq!(
222→            action,
223→            RecoveryAction::CustomFix("chmod +x script.sh".to_string())
224→        );
