149→/// Inner loop for yes/no prompt, separated so the caller can ensure cursor cleanup.
150→fn prompt_yes_no_loop(
151→    term: &Term,
152→    options: &[PromptOption],
153→    sel: &mut usize,
154→    pad: &str,
155→    active_prefix: &Style,
156→    active_style: &Style,
157→    inactive_prefix: &Style,
158→    inactive_style: &Style,
159→    prompt: &Prompt,
160→) -> Result<PromptResult> {
