162→        // Draw option lines
163→        for (i, opt) in options.iter().enumerate() {
164→            let line = if i == *sel {
165→                format!(
166→                    "{}{} {}",
167→                    pad,
168→                    active_prefix.apply_to("›"),
169→                    active_style.apply_to(&opt.label)
170→                )
171→            } else {
172→                format!(
173→                    "{}{} {}",
174→                    pad,
175→                    inactive_prefix.apply_to("·"),
176→                    inactive_style.apply_to(&opt.label)
177→                )
178→            };
179→            term.write_line(&line).map_err(BivvyError::Io)?;
180→        }
181→        term.flush().map_err(BivvyError::Io)?;
182→
183→        // Read key — propagate errors (e.g. EOF from Ctrl+D) to caller for cleanup
184→        let key = term.read_key().map_err(BivvyError::Io)?;
185→
186→        let chosen = match key {
187→            Key::Char('y') | Key::Char('Y') => options.iter().position(|o| o.value == "yes"),
188→            Key::Char('n') | Key::Char('N') => options.iter().position(|o| o.value == "no"),
189→            Key::Enter | Key::Char(' ') => Some(*sel),
190→            Key::ArrowDown | Key::Tab | Key::Char('j') => {
191→                *sel = (*sel + 1) % options.len();
192→                None
193→            }
194→            Key::ArrowUp | Key::BackTab | Key::Char('k') => {
195→                *sel = (*sel + options.len() - 1) % options.len();
196→                None
197→            }
198→            // Ctrl+D (EOF character) — treat as abort
199→            Key::Char('\x04') => {
200→                term.clear_last_lines(options.len())
201→                    .map_err(BivvyError::Io)?;
202→                return Err(BivvyError::Io(std::io::Error::new(
203→                    std::io::ErrorKind::UnexpectedEof,
204→                    "EOF (Ctrl+D)",
205→                )));
206→            }
207→            _ => None,
208→        };
209→
210→        if let Some(idx) = chosen {
211→            // Clear option lines
212→            term.clear_last_lines(options.len())
213→                .map_err(BivvyError::Io)?;
214→            // Clear the prompt question line
215→            term.clear_last_lines(1).map_err(BivvyError::Io)?;
216→            // Re-print prompt with selection (show "yes" or "no")
217→            let answer_text = if options[idx].value == "yes" {
218→                "yes"
219→            } else {
220→                "no"
221→            };
222→            term.write_line(&format!(
223→                "{} {}",
224→                prompt.question,
225→                Style::new().bold().apply_to(answer_text)
226→            ))
227→            .map_err(BivvyError::Io)?;
228→
229→            return Ok(PromptResult::String(options[idx].value.clone()));
230→        }
231→
232→        // Clear option lines for redraw
233→        term.clear_last_lines(options.len())
234→            .map_err(BivvyError::Io)?;
235→    }
236→}
