244→
245→    let default_values: Vec<&str> = prompt
246→        .default
247→        .as_deref()
248→        .map(|d| d.split(',').collect())
249→        .unwrap_or_default();
250→    let defaults: Vec<bool> = options
251→        .iter()
252→        .map(|o| default_values.contains(&o.value.as_str()))
253→        .collect();
254→
255→    let selections = MultiSelect::with_theme(&prompt_theme())
256→        .with_prompt(&prompt.question)
257→        .items(&labels)
258→        .defaults(&defaults)
259→        .interact_on(term)
260→        .map_err(map_dialoguer_err)?;
261→
262→    let values: Vec<String> = selections
263→        .iter()
264→        .map(|&i| options[i].value.clone())
265→        .collect();
266→
267→    Ok(PromptResult::Strings(values))
